from fastmcp import FastMCP
import os
from google.cloud import bigquery

# ── Server instance ────────────────────────────────────────────────────────
mcp = FastMCP("source_connection", description="Consulta la tabla info.soucree en BigQuery")

# ── Tool: source_connection ──────────────────────────────────────────────────
@mcp.tool()
def source_connection() -> str:
    """Consulta la tabla info.soucree en BigQuery

    Returns:
        Resultado de la operación en JSON/texto
    """
    # Implementation
    credentials = os.getenv('GOOGLE_APPLICATION_CREDENTIALS')
    client = bigquery.Client.from_service_account_json(credentials)
